    private void cbxOpcionesActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_cbxOpcionesActionPerformed
        // TODO add your handling code here:
        String opciones = (String)cbxOpciones.getSelectedItem();
        if (opciones.equals("Opción 1"))
            lblImagen.setIcon(new javax.swing.ImageIcon(getClass().getResource("/img/Diapositiva5.JPG")));
        if (opciones.equals("Opción 2"))
            lblImagen.setIcon(new javax.swing.ImageIcon(getClass().getResource("/img/Diapositiva7.JPG")));
        if (opciones.equals("Opción 3"))
            lblImagen.setIcon(new javax.swing.ImageIcon(getClass().getResource("/img/Diapositiva8.JPG")));
       // lblImagen.setText(opciones);
    }//GEN-LAST:event_cbxOpcionesActionPerformed

